// Generated by `just generate` from `src/plugins/claudetto/slices/reply/lab/reply.test.ts`. Edit the source and run `just generate`.
// Lab tests of the `reply` slice: the `Reply` button under a message of Claude, and the `>` quote that a press puts in the prompt box.
// The bottom of the render chain draws the message as the engine does, and the stub of `prompt.fill` records the text and the mode.
// The file is self-contained, because `just generate` copies it to `tests/` of the plugin, where it cannot import a relative file.

import type { On } from "claude-code";
import { type Engine, expect, test } from "claude-code/testing";

const PLUGIN = "claudetto";

const stub = (on: On) => {
  const fills: { text: string; mode?: string }[] = [];
  on("ui.render", ($, e) => $.ui.resolve(e).Text({ children: "message" }));
  on("prompt.fill", (_$, e) => {
    fills.push({ text: e.text, mode: e.mode });
    return { isFilled: true };
  });
  return fills;
};

const mount = ($: Engine, text: string, id = "m1") =>
  $.ui.mount({
    plugin: PLUGIN,
    surface: "terminal",
    component: "AssistantMessage",
    requestId: id,
    props: { text, isFirstOfReply: true },
  });

test("a press of `Reply` fills the prompt with the message as a `>` quote", async ($: Engine, on: On) => {
  const fills = stub(on);
  const ui = await mount($, "First line.\nSecond line.");
  expect(await ui.find({ type: "Text", text: /message/ })).toBeDefined();
  await ui.press({ key: "reply" });
  await ui.unmount();
  expect(fills).toStrictEqual([
    { text: "> First line.\n> Second line.\n\n", mode: "insert" },
  ]);
});

test("a message with no text gets no `Reply` button", async ($: Engine, on: On) => {
  stub(on);
  const ui = await mount($, "  ");
  expect(await ui.find({ key: "reply" })).toBeUndefined();
  await ui.unmount();
});
